import{describe,it,expect}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function readExplorerFile(e){return readFileSync(resolve(__dirname,"../../frontend/vayu-sena-medal-explorer",e),"utf-8")}function readLandingPage(){return readFileSync(resolve(__dirname,"../../frontend/awards-of-india-explorer/index.html"),"utf-8")}describe("Vayu Sena Medal Explorer — Page Structure",()=>{let e;beforeAll(()=>{e=readExplorerFile("index.html")}),it("contains a hero section with page title and kicker",()=>{expect(e).toContain('class="vsm-hero-title"'),expect(e).toContain("Vayu Sena Medal Explorer"),expect(e).toContain("Indian Air Force Gallantry Honour"),expect(e).toContain("Instituted:"),expect(e).toContain("1960")}),it("contains all required content sections from the issue",()=>{["history","eligibility","medal-design","air-operations","selection","awardees","timeline","facts","gallery"].forEach(t=>{expect(e).toContain(`id="${t}"`),expect(e).toContain(`data-tab="${t}"`)})}),it("contains the key historical and operational details",()=>{expect(e).toContain("18-Pres/60"),expect(e).toContain("Sena Medal"),expect(e).toContain("Nao Sena Medal"),expect(e).toContain("Operation Safed Sagar"),expect(e).toContain("Himalayan Eagle")}),it("has a semantic heading hierarchy (single h1, section h2s)",()=>{const t=(e.match(/<h1[\s>]/g)||[]).length,a=(e.match(/<h2[\s>]/g)||[]).length;expect(t).toBe(1),expect(a).toBeGreaterThanOrEqual(9)}),it("uses HTTPS image sources with alt attributes",()=>{const t=e.match(/<img [^>]*>/g)||[];expect(t.length).toBeGreaterThanOrEqual(6),t.forEach(e=>{expect(e).toMatch(/src="https:\/\//),expect(e).toMatch(/alt="/),expect(e).not.toMatch(/src="http:\/\//)})}),it("links the shared stylesheet, page stylesheet, and script",()=>{expect(e).toContain('href="../../styles.css"'),expect(e).toContain('href="style.css"'),expect(e).toContain('src="script.js"')})}),describe("Vayu Sena Medal Explorer — Assets",()=>{it("includes a non-empty stylesheet",()=>{const e=readExplorerFile("style.css");expect(e.length).toBeGreaterThan(1e3),expect(e).toContain(".vsm-hero")}),it("includes a valid interactive script with required functions",()=>{const e=readExplorerFile("script.js");expect(e).toContain("initTabs"),expect(e).toContain("initRecipientSearch"),expect(e).toContain("document.addEventListener('DOMContentLoaded'")})}),describe("Vayu Sena Medal — Landing Page Integration",()=>{it("is listed as a card on the Awards of India Explorer landing page",()=>{const e=readLandingPage();expect(e).toContain("Vayu Sena Medal"),expect(e).toContain("../vayu-sena-medal-explorer/index.html")}),it("matches the existing award card pattern (icon, category, stats, button)",()=>{const e=readLandingPage(),t=e.indexOf("Vayu Sena Medal Card");expect(t).toBeGreaterThan(-1);const a=e.slice(t,t+1200);expect(a).toContain("award-icon"),expect(a).toContain("award-category"),expect(a).toContain("award-year"),expect(a).toContain("award-btn"),expect(a).toContain('class="award-card glass-card"')})});